/** Stamped in by vite.config.ts at build time (see buildInfo there). */
declare const __BUILD__: {
  /** package.json version */
  version: string
  /** short commit hash, or "dev" when there's no git */
  sha: string
  /** ISO time the build (or dev server) started */
  date: string
  /** true under the dev server */
  dev: boolean
}
